<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Security;
use EventMenu\Services\CounterOrderService;
use EventMenu\Services\PaymentService;

Auth::requirePermission('orders.create');$tenantId=em_require_tenant();$unitId=Auth::unitId();
if($_SERVER['REQUEST_METHOD']==='POST'){em_post_csrf();try{$cart=[];foreach((array)($_POST['qty']??[])as$id=>$qty){$q=max(0,min(50,(int)$qty));if($q>0)$cart[]=['product_id'=>(int)$id,'qty'=>$q,'option_ids'=>(array)($_POST['option_ids'][(int)$id]??[])];}$result=(new CounterOrderService())->create($cart,['name'=>(string)($_POST['customer_name']??''),'phone'=>(string)($_POST['customer_phone']??'')],(string)($_POST['notes']??''));$manualMethod=(string)($_POST['manual_method']??'');if($manualMethod!==''&&Auth::can('payments.manage')){if(!in_array($manualMethod,['cash','card','pix','other'],true))throw new RuntimeException('Forma de recebimento inválida.');$payment=new PaymentService();$payment->create((int)$result['order_id'],'manual','pos-manual:'.$tenantId.':'.$result['order_id'].':'.bin2hex(random_bytes(8)));$payment->confirmVerified(['tenant_id'=>$tenantId,'order_id'=>(int)$result['order_id'],'provider'=>'manual','provider_payment_id'=>'POS-'.strtoupper(bin2hex(random_bytes(10))),'amount_cents'=>(int)$result['total_cents'],'currency'=>'BRL','account_reference'=>'manual','manual_method'=>$manualMethod]);Auth::audit('pos.sale_paid','order',(string)$result['order_id'],['method'=>$manualMethod]);header('Location: '.em_url('/retirada.php?t='.rawurlencode((string)$result['fulfillment_token']).'&auto=1'));exit;}em_flash('ok','Pedido de balcão #'.$result['order_id'].' criado. Estoque comprometido. Confirme o pagamento para liberar a retirada.');em_go(Auth::role()==='counter'?'counter-orders':'orders',Auth::role()==='counter'?[]:['view'=>(int)$result['order_id']]);}catch(Throwable$e){if(isset($result['order_id'])){em_flash('error','Venda #'.$result['order_id'].' foi criada, mas o pagamento não foi confirmado: '.$e->getMessage());em_go(Auth::role()==='counter'?'counter-orders':'orders',Auth::role()==='counter'?[]:['view'=>(int)$result['order_id']]);}em_flash('error',$e->getMessage());em_go('pos');}}
$where='p.tenant_id=? AND p.active=1';$args=[$tenantId];if($unitId){$where.=' AND (p.unit_id IS NULL OR p.unit_id=?)';$args[]=$unitId;}$p=$pdo->prepare('SELECT p.*,c.name category_name,bu.name unit_name FROM products p LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN business_units bu ON bu.id=p.unit_id WHERE '.$where.' ORDER BY p.featured DESC,COALESCE(c.sort_order,9999),c.name,p.name');$p->execute($args);$products=$p->fetchAll();$ids=array_map(fn($p)=>(int)$p['id'],$products);$groups=[];$options=[];if($ids){$marks=implode(',',array_fill(0,count($ids),'?'));$g=$pdo->prepare('SELECT * FROM product_option_groups WHERE tenant_id=? AND product_id IN ('.$marks.') AND active=1 ORDER BY product_id,sort_order,id');$g->execute([$tenantId,...$ids]);foreach($g->fetchAll()as$r)$groups[(int)$r['product_id']][]=$r;$gids=[];foreach($groups as$rs)foreach($rs as$r)$gids[]=(int)$r['id'];if($gids){$marks=implode(',',array_fill(0,count($gids),'?'));$o=$pdo->prepare('SELECT * FROM product_options WHERE group_id IN ('.$marks.') AND active=1 ORDER BY group_id,sort_order,id');$o->execute($gids);foreach($o->fetchAll()as$r)$options[(int)$r['group_id']][]=$r;}}$grouped=[];foreach($products as$product)$grouped[$product['category_name']?:'Outros'][]=$product;
em_header('PDV / Balcão','pos');?>
<form method="post" id="pos-form"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><div class="grid" style="grid-template-columns:minmax(0,2fr) minmax(320px,1fr);align-items:start"><section><?php foreach($grouped as$category=>$rows):?><article class="card" style="margin-bottom:16px"><div class="section-head"><h2><?= Security::e($category) ?></h2><span class="muted"><?= count($rows) ?> itens</span></div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(250px,1fr))"><?php foreach($rows as$product):?><div style="padding:15px;border:1px solid var(--line);border-radius:18px"><div class="section-head"><div><strong><?= Security::e($product['name']) ?></strong><?php if($product['badge']):?> <span class="badge"><?= Security::e($product['badge']) ?></span><?php endif;?><div class="muted"><?= Security::e($product['unit_name']??'Todas as unidades') ?></div></div><?php if($product['featured']):?><span class="badge active">Destaque</span><?php endif;?></div><div class="price" style="margin:8px 0"><?php if($product['promo_price_cents']!==null):?><s class="muted"><?= em_money($product['price_cents']) ?></s> <strong><?= em_money($product['promo_price_cents']) ?></strong><?php else:?><?= em_money($product['price_cents']) ?><?php endif;?></div><?php if((int)$product['track_stock']):?><small class="muted">Estoque: <?= Security::e((string)$product['stock_qty']) ?><?php if($product['min_stock_qty']!==null):?> · mínimo <?= Security::e((string)$product['min_stock_qty']) ?><?php endif;?></small><?php endif;?><?php foreach($groups[(int)$product['id']]??[]as$gr):?><fieldset style="border:0;padding:8px 0;margin:8px 0"><legend><strong><?= Security::e($gr['name']) ?></strong> <small class="muted">mín. <?= (int)$gr['min_select'] ?> · máx. <?= (int)$gr['max_select'] ?></small></legend><?php foreach($options[(int)$gr['id']]??[]as$op):?><label style="display:flex;justify-content:space-between;gap:8px;padding:4px 0"><span><input type="<?= (int)$gr['max_select']===1?'radio':'checkbox' ?>" name="option_ids[<?= (int)$product['id'] ?>]<?= (int)$gr['max_select']===1?'':'[]' ?>" value="<?= (int)$op['id'] ?>"> <?= Security::e($op['name']) ?></span><span class="muted"><?= (int)$op['price_delta_cents']?(((int)$op['price_delta_cents']>0?'+ ':'- ').em_money(abs((int)$op['price_delta_cents']))):'' ?></span></label><?php endforeach;?></fieldset><?php endforeach;?><label style="margin-top:10px">Quantidade<input type="number" name="qty[<?= (int)$product['id'] ?>]" min="0" max="50" value="0" inputmode="numeric"></label></div><?php endforeach;?></div></article><?php endforeach;?><?php if(!$products):?><section class="card"><h2>Sem produtos</h2><p class="muted">Cadastre produtos ativos para esta unidade antes de usar o PDV.</p></section><?php endif;?></section><aside class="card" style="position:sticky;top:18px"><div class="section-head"><h2>Nova venda</h2><?php if($unitId):?><span class="badge active">Unidade #<?= $unitId ?></span><?php endif;?></div><p class="muted">Preço promocional, adicionais, combos e estoque são recalculados no servidor.</p><label>Cliente <input name="customer_name" maxlength="160" placeholder="Opcional"></label><label>Telefone <input name="customer_phone" maxlength="30" autocomplete="tel" placeholder="Opcional"></label><label>Observações<textarea name="notes" maxlength="1000" placeholder="Ex.: cliente vai retirar aos poucos"></textarea></label><?php if(Auth::can('payments.manage')):?><label>Recebimento<select name="manual_method"><option value="">Criar sem receber agora</option><option value="cash">Dinheiro</option><option value="card">Cartão / maquininha</option><option value="pix">Pix externo</option><option value="other">Outro</option></select></label><p class="muted">Ao receber, o caixa precisa estar aberto. O comprovante de retirada abre automaticamente.</p><?php else:?><div class="alert">Seu perfil cria a venda, mas não confirma pagamento. Um Caixa/Gerente deverá receber.</div><?php endif;?><button class="primary" style="width:100%"<?= !$products?' disabled':'' ?>>Finalizar venda</button><p class="muted" style="margin-top:12px"><strong>Retirada parcial:</strong> 5 cervejas compradas podem ser retiradas em etapas sem baixar estoque duas vezes.</p></aside></div></form><?php em_footer();
